def comprimir_repeticiones(texto: str) -> str:
    """
    Agrupa los caracteres iguales y consecutivos del texto.
    Cada grupo se representa como el carácter seguido de su cantidad.
    """
    if not texto:
        return ""

    resultado = []
    actual = texto[0]
    contador = 1

    for c in texto[1:]:
        if c == actual:
            contador += 1
        else:
            resultado.append(actual + str(contador))
            actual = c
            contador = 1

    # Añadir el último grupo
    resultado.append(actual + str(contador))

    return "".join(resultado)

def aplana(datos: list) -> list:
    """
    Aplana una lista que puede contener anidaciones de listas y tuplas.
    Devuelve una nueva lista con todos los elementos que no son listas ni tuplas,
    en el mismo orden en que aparecen.
    """
    def _flatten(seq):
        result = []
        for item in seq:
            if isinstance(item, (list, tuple)):
                # Recursivamente aplanar la sublista o tupla
                result.extend(_flatten(item))
            else:
                result.append(item)
        return result

    return _flatten(datos)

import csv
from io import StringIO

def parsear_ventas(texto: str) -> list[dict]:
    # Dividir el texto en líneas, ignorando las vacías o con solo espacios
    lines = texto.splitlines()
    non_empty_lines = [line for line in lines if line.strip() != ""]

    # Si no hay ninguna línea, retornar lista vacía
    if not non_empty_lines:
        return []

    # Verificar la cabecera
    header = non_empty_lines[0].strip()
    expected_header = "fecha,producto,cantidad,precio"
    if header != expected_header:
        raise ValueError("Cabecera incorrecta")

    # Procesar las filas restantes como CSV
    remaining_text = "\n".join(non_empty_lines[1:])
    if not remaining_text:
        return []

    reader = csv.reader(StringIO(remaining_text))
    result = []
    for row in reader:
        if len(row) != 4:
            raise ValueError("Fila con número incorrecto de campos")

        fecha, producto, cantidad_str, precio_str = row

        # Validar cantidad
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError("Cantidad no es un entero válido")
        if cantidad < 0:
            raise ValueError("Cantidad negativa")

        # Validar precio
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError("Precio no es un número válido")

        result.append({
            "fecha": fecha,
            "producto": producto,
            "cantidad": cantidad,
            "precio": precio
        })

    return result

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

def mochila(pesos: list[int], valores: list[int], capacidad: int) -> tuple[int, list[int]]:
    # Validación de entradas
    if len(pesos) != len(valores):
        raise ValueError("Las listas de pesos y valores deben tener la misma longitud.")
    if any(w < 0 for w in pesos):
        raise ValueError("Los pesos no pueden ser negativos.")
    if capacidad < 0:
        raise ValueError("La capacidad no puede ser negativa.")

    n = len(pesos)
    if n == 0:
        return (0, [])

    best_key = None
    best_indices = []

    # Enumerar todos los subconjuntos (máscara de bits)
    for mask in range(1 << n):
        total_weight = 0
        total_value = 0
        indices = []
        for i in range(n):
            if (mask >> i) & 1:
                total_weight += pesos[i]
                total_value += valores[i]
                indices.append(i)
        # Descartar si excede la capacidad
        if total_weight > capacidad:
            continue

        indices.sort()
        count = len(indices)

        # Criterios de desempate: mayor valor (min -valor),
        # menor peso, menor número de objetos, lista lexicográficamente menor
        key = (-total_value, total_weight, count, indices)

        if best_key is None or key < best_key:
            best_key = key
            best_indices = indices

    # Si no se encontró ninguna solución (el conjunto vacío siempre cabe cuando capacidad >= 0)
    if best_key is None:
        return (0, [])

    total_val = -best_key[0]
    return (total_val, best_indices)

from collections import OrderedDict

class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("La capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Marcar como más recientemente usado
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        # Con capacidad 0 no se guarda nada
        if self.capacidad == 0:
            return
        # Si la clave ya existe, actualizar y mover al final
        if clave in self._datos:
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
            return
        # Si la caché está llena, descartar la menos usada
        if len(self._datos) >= self.capacidad:
            self._datos.popitem(last=False)
        # Insertar la nueva clave
        self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
